\"\"\"Minimal OpenAI Responses API client using only the Python standard library.\"\"\"

import json
import os
import sys
import urllib.error
import urllib.request

API_URL = \"https://api.openai.com/v1/responses\"
DEFAULT_MODEL = \"gpt-4o-mini\"


class OpenAIError(Exception):
    pass


def send_prompt(prompt, model=DEFAULT_MODEL, api_key=None, instructions=None, timeout=60):
    \"\"\"Send a text prompt to the Responses API and return the reply text.

    The request sets "'``store`` to False so OpenAI does not retain the response.
    The API key is read from the OPENAI_API_KEY environment variable by default.
    """
    api_key = api_key or os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise OpenAIError("Set OPENAI_API_KEY or pass api_key.")

    payload = {"model": model, "input": prompt, "store": False}
    if instructions:
        payload["instructions"] = instructions

    request = urllib.request.Request(
        API_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + api_key,
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            body = json.load(response)
    except urllib.error.HTTPError as error:
        detail = error.read().decode("utf-8", errors="replace")
        raise OpenAIError("HTTP %d: %s" % (error.code, detail)) from None
    except urllib.error.URLError as error:
        raise OpenAIError("Request failed: %s" % error.reason) from None

    return extract_text(body)


def extract_text(body):
    if isinstance(body.get("output_text"), str):
        return body["output_text"]
    parts = []
    for item in body.get("output", []):
        if item.get("type") == "message":
            for content in item.get("content", []):
                if content.get("type") == "output_text":
                    parts.append(content.get("text", ""))
    return "".join(parts)


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    prompt = " ".join(argv) if argv else sys.stdin.read()
    if not prompt.strip():
        print("Usage: openai_client.py PROMPT (or pipe prompt on stdin)", file=sys.stderr)
        return 2
    try:
        print(send_prompt(prompt))
    except OpenAIError as error:
        print("Error: %s" % error, file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
